import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_matvec_forward(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// CTA-level tiling over M: each block computes RowsPerBlock output elements,
// staging a K-tile of B into shared memory once and reusing it across all
// rows handled by the block. This significantly reduces redundant global
// memory traffic for B (previously re-read from global memory M times).
template <typename T, int Threads, int RowsPerBlock, int TileK>
__global__ void matvec_kernel(
    const T* __restrict__ Aptr,
    const T* __restrict__ Bptr,
    T* __restrict__ Cptr,
    int M, int K, int kChunk)
{
  // Split-K: each block handles a contiguous [kStart, kEnd) range of K so
  // that, together with the row tiling below, we launch enough CTAs to
  // keep the GPU busy even though M is comparatively small relative to K.
  int kStart = blockIdx.y * kChunk;
  if (kStart >= K) return;
  int kEnd = min(K, kStart + kChunk);
  extern __shared__ float Bs[];  // 2*TileK floats (double-buffered)
  float* Bs0 = Bs;
  float* Bs1 = Bs + TileK;
  int block_row_start = blockIdx.x * RowsPerBlock;
  int tid = threadIdx.x;
  float acc[RowsPerBlock];
  #pragma unroll
  for (int r = 0; r < RowsPerBlock; ++r) acc[r] = 0.0f;
  constexpr int VecWidth = 4;
  int localK = kEnd - kStart;
  int numTiles = (localK + TileK - 1) / TileK;
  const T* Bptr_local = Bptr + kStart;
  // Cooperative vectorized load of a B tile into the given shared buffer.
  auto load_tile = [&](int tileIdx, float* dst) {
    int k0 = tileIdx * TileK;
    int chunk = min(TileK, localK - k0);
    int chunk4 = chunk / VecWidth;
    int rem_start = chunk4 * VecWidth;
    const float4* Bsrc4 = reinterpret_cast<const float4*>(Bptr_local + k0);
    float4* Bdst4 = reinterpret_cast<float4*>(dst);
    for (int i = tid; i < chunk4; i += Threads) {
      Bdst4[i] = Bsrc4[i];
    }
    for (int i = rem_start + tid; i < chunk; i += Threads) {
      dst[i] = Bptr_local[k0 + i];
    }
  };
  // Prologue: load the first tile before the pipelined loop begins.
  load_tile(0, Bs0);
  __syncthreads();
  for (int t = 0; t < numTiles; ++t) {
    float* curBuf = (t & 1) ? Bs1 : Bs0;
    float* nxtBuf = (t & 1) ? Bs0 : Bs1;
    int k0 = t * TileK;
    int chunk = min(TileK, localK - k0);
    int chunk4 = chunk / VecWidth;
    int rem_start = chunk4 * VecWidth;
    // Prefetch the next tile into the other buffer while computing on the
    // current buffer, overlapping global-memory latency with compute.
    if (t + 1 < numTiles) {
      load_tile(t + 1, nxtBuf);
    }
    // Vectorized compute using shared B tile, reused across all rows.
    float4* curBuf4 = reinterpret_cast<float4*>(curBuf);
    for (int i = tid; i < chunk4; i += Threads) {
      float4 b4 = curBuf4[i];
      #pragma unroll
      for (int r = 0; r < RowsPerBlock; ++r) {
        int m = block_row_start + r;
        if (m < M) {
          const float4* Aptr4 = reinterpret_cast<const float4*>(Aptr + (size_t)m * K + kStart + k0);
          float4 a4 = __ldcs(Aptr4 + i);
          acc[r] += a4.x * b4.x + a4.y * b4.y + a4.z * b4.z + a4.w * b4.w;
        }
      }
    }
    // Scalar remainder.
    for (int i = rem_start + tid; i < chunk; i += Threads) {
      float bv = curBuf[i];
      #pragma unroll
      for (int r = 0; r < RowsPerBlock; ++r) {
        int m = block_row_start + r;
        if (m < M) {
          float av = __ldcs(Aptr + ((size_t)m * K + kStart + k0 + i));
          acc[r] += av * bv;
        }
      }
    }
    // Ensure the current buffer's reads are complete (safe to overwrite in a
    // future iteration) and the prefetch write to nxtBuf is visible before it
    // becomes the current buffer next iteration.
    __syncthreads();
  }
  // Block-level reduction per row: warp shuffle then shared memory across warps.
  unsigned mask = 0xffffffffu;
  int lane = tid % 32;
  int warp_id = tid / 32;
  constexpr int NumWarps = Threads / 32;
  __shared__ float warp_sums[RowsPerBlock][NumWarps];
  #pragma unroll
  for (int r = 0; r < RowsPerBlock; ++r) {
    float val = acc[r];
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      val += __shfl_down_sync(mask, val, offset);
    }
    if (lane == 0) {
      warp_sums[r][warp_id] = val;
    }
  }
  __syncthreads();
  if (warp_id == 0) {
    #pragma unroll
    for (int r = 0; r < RowsPerBlock; ++r) {
      float val = (lane < NumWarps) ? warp_sums[r][lane] : 0.0f;
      #pragma unroll
      for (int offset = 16; offset > 0; offset >>= 1) {
        val += __shfl_down_sync(mask, val, offset);
      }
      if (lane == 0) {
        int m = block_row_start + r;
        if (m < M) {
          // Multiple K-split blocks contribute partial sums to the same
          // output element, so accumulate atomically. C is zero-initialized
          // on the host side before launch.
          atomicAdd(&Cptr[m], static_cast<T>(val));
        }
      }
    }
  }
}
torch::Tensor cute_matvec_forward(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2, "A must be 2D (M,K)");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");
  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  int M = (int)A_c.size(0);
  int K = (int)A_c.size(1);
  int64_t Bnum = B_c.numel();
  TORCH_CHECK(Bnum == K, "B must have K elements");
  // C must start at zero because split-K partial sums are accumulated
  // into it via atomicAdd across the grid's y-dimension.
  auto C = torch::zeros({M, 1}, A.options());
  const float* Aptr = A_c.data_ptr<float>();
  const float* Bptr = B_c.data_ptr<float>();
  float* Cptr = C.data_ptr<float>();
  constexpr int Threads = 256;
  constexpr int RowsPerBlock = 32;
  constexpr int TileK = 1024;
  // Split-K: with very large K and relatively small M, a single K-pass per
  // row-block launches too few CTAs to saturate the GPU (grid.x alone is
  // only M/RowsPerBlock). Splitting K across multiple blocks along grid.y,
  // with partial results combined via atomicAdd, increases the number of
  // concurrently schedulable CTAs and improves SM occupancy while each
  // block still streams a manageable K-range through the double-buffered
  // shared-memory pipeline.
  constexpr int SplitK = 8;
  int kChunkBase = (K + SplitK - 1) / SplitK;
  int kChunk = ((kChunkBase + TileK - 1) / TileK) * TileK;
  if (kChunk <= 0) kChunk = TileK;
  dim3 block(Threads);
  dim3 grid((unsigned)((M + RowsPerBlock - 1) / RowsPerBlock), (unsigned)SplitK);
  size_t smem_bytes = (size_t)2 * TileK * sizeof(float);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  matvec_kernel<float, Threads, RowsPerBlock, TileK><<<grid, block, smem_bytes, stream>>>(
      Aptr, Bptr, Cptr, M, K, kChunk);
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "matvec_kernel launch failed: ", cudaGetErrorString(err));
  return C;
}
"""

cute_matvec_ext = load_inline(
    name="cute_matvec_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_matvec_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix-vector multiplication (C = A * B) implemented with a custom CUTE kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_matvec_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matvec_forward(A.contiguous(), B.contiguous())

